//! Builds the incurs command tree from the Swift CLI's `--experimental-dump-help` output.
//!
//! Every command becomes a raw incurs command backed by the linked Swift code, so the
//! tree only has to describe the commands; Swift keeps parsing their arguments.

use incurs::cli::Cli;
use incurs::command::CommandDef;
use serde::Deserialize;

use crate::swift::SwiftCommand;

/// The spec checked in next to this crate, regenerated by `scripts/update-spec.sh`.
pub const SPEC_JSON: &str = include_str!("../spec/tuist.spec.json");

#[derive(Deserialize)]
struct Spec {
    command: SpecCommand,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SpecCommand {
    command_name: String,
    #[serde(rename = "abstract")]
    summary: Option<String>,
    discussion: Option<String>,
    #[serde(default = "default_true")]
    should_display: bool,
    default_subcommand: Option<String>,
    #[serde(default)]
    arguments: Vec<SpecArgument>,
    #[serde(default)]
    subcommands: Vec<SpecCommand>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SpecArgument {
    kind: String,
    #[serde(rename = "abstract")]
    summary: Option<String>,
    #[serde(default)]
    names: Vec<SpecName>,
    value_name: Option<String>,
    #[serde(default = "default_true")]
    should_display: bool,
    #[serde(default)]
    is_optional: bool,
    #[serde(default)]
    is_repeating: bool,
}

#[derive(Deserialize)]
struct SpecName {
    kind: String,
    name: String,
}

fn default_true() -> bool {
    true
}

/// Builds the full `tuist` command tree, with a raw root that receives anything the
/// tree cannot run (plugin tasks, `--help`, unknown commands).
pub fn build_cli() -> Cli {
    let spec: Spec = serde_json::from_str(SPEC_JSON).expect("checked-in spec is valid JSON");
    let root = spec.command;
    let mut cli = Cli::create(root.command_name.clone())
        .root(
            CommandDef::build(root.command_name.clone(), SwiftCommand)
                .description(root.summary.clone().unwrap_or_default())
                .raw()
                .hidden()
                .done(),
        );
    if let Some(summary) = &root.summary {
        cli = cli.description(summary.clone());
    }
    add_subcommands(cli, &root, &[root.command_name.clone()], true)
}

fn add_subcommands(mut cli: Cli, parent: &SpecCommand, path: &[String], visible: bool) -> Cli {
    for command in &parent.subcommands {
        let mut command_path = path.to_vec();
        command_path.push(command.command_name.clone());
        let visible = visible && command.should_display;
        if command.subcommands.is_empty() {
            cli = cli.command(command.command_name.clone(), leaf(command, &command_path, visible));
        } else {
            let mut group = Cli::create(command.command_name.clone());
            if let Some(summary) = &command.summary {
                group = group.description(summary.clone());
            }
            if let Some(default) = &command.default_subcommand {
                group = group.default_command(default.clone());
            }
            cli = cli.group(add_subcommands(group, command, &command_path, visible));
        }
    }
    cli
}

fn leaf(command: &SpecCommand, path: &[String], visible: bool) -> CommandDef {
    let mut builder = CommandDef::build(command.command_name.clone(), SwiftCommand)
        .description(command.summary.clone().unwrap_or_default())
        .hint(usage(command, path))
        .raw();
    if !visible {
        builder = builder.hidden();
    }
    builder.done()
}

/// Renders the command's real arguments, so agents reading `--llms-full` or skills see
/// the flags the Swift parser accepts rather than the raw `arguments` array alone.
fn usage(command: &SpecCommand, path: &[String]) -> String {
    let arguments: Vec<&SpecArgument> = command
        .arguments
        .iter()
        .filter(|argument| argument.should_display)
        .collect();
    let positionals: Vec<String> = arguments
        .iter()
        .filter(|argument| argument.kind == "positional")
        .map(|argument| {
            let name = argument.value_name.clone().unwrap_or_else(|| "value".into());
            let name = if argument.is_repeating { format!("{name}...") } else { name };
            if argument.is_optional { format!("[<{name}>]") } else { format!("<{name}>") }
        })
        .collect();
    let mut lines = vec![format!(
        "Usage: {} [options]{}{}",
        path.join(" "),
        if positionals.is_empty() { "" } else { " " },
        positionals.join(" ")
    )];
    let options: Vec<String> = arguments
        .iter()
        .filter(|argument| argument.kind != "positional")
        .map(|argument| {
            let mut names: Vec<String> = argument
                .names
                .iter()
                .map(|name| match name.kind.as_str() {
                    "short" => format!("-{}", name.name),
                    "longWithSingleDash" => format!("-{}", name.name),
                    _ => format!("--{}", name.name),
                })
                .collect();
            names.sort_by_key(|name| !name.starts_with("--"));
            let value = match (argument.kind.as_str(), &argument.value_name) {
                ("option", Some(value)) => format!(" <{value}>"),
                _ => String::new(),
            };
            let summary = argument.summary.as_deref().unwrap_or("");
            format!("  {}{value}  {summary}", names.join(", "))
        })
        .collect();
    if !options.is_empty() {
        lines.push("Options:".into());
        lines.extend(options);
    }
    if let Some(discussion) = &command.discussion {
        lines.push(String::new());
        lines.push(discussion.clone());
    }
    lines.join("\n")
}
